create table public.group_chats(id uuid primary key default gen_random_uuid(), name text not null check(char_length(name) between 1 and 80), owner_id uuid not null references public.profiles(id), created_at timestamptz not null default now()); grant select,update,delete on public.group_chats to authenticated; grant all on public.group_chats to service_role; alter table public.group_chats enable row level security; create table public.group_members(group_id uuid not null references public.group_chats(id) on delete cascade,user_id uuid not null references public.profiles(id),joined_at timestamptz not null default now(),primary key(group_id,user_id)); grant select,delete on public.group_members to authenticated; grant all on public.group_members to service_role; alter table public.group_members enable row level security; create function public.is_group_member(_group uuid,_user uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.group_members where group_id=_group and user_id=_user) $$; revoke all on function public.is_group_member(uuid,uuid) from public,anon; grant execute on function public.is_group_member(uuid,uuid) to authenticated; create policy "group members read chats" on public.group_chats for select to authenticated using(public.is_group_member(id,auth.uid())); create policy "group owner edits" on public.group_chats for update to authenticated using(owner_id=auth.uid()) with check(owner_id=auth.uid()); create policy "group owner deletes" on public.group_chats for delete to authenticated using(owner_id=auth.uid()); create policy "group members read members" on public.group_members for select to authenticated using(public.is_group_member(group_id,auth.uid())); create policy "group member leaves" on public.group_members for delete to authenticated using(user_id=auth.uid()); create table public.group_messages(id uuid primary key default gen_random_uuid(),group_id uuid not null references public.group_chats(id) on delete cascade,author_id uuid not null references public.profiles(id),content text not null check(char_length(content)<=2000),media_url text,created_at timestamptz not null default now()); grant select,insert,delete on public.group_messages to authenticated; grant all on public.group_messages to service_role; alter table public.group_messages enable row level security; create policy "group members read messages" on public.group_messages for select to authenticated using(public.is_group_member(group_id,auth.uid())); create policy "group members send" on public.group_messages for insert to authenticated with check(author_id=auth.uid() and public.is_group_member(group_id,auth.uid()) and not public.is_suspended(auth.uid())); create policy "group members delete own" on public.group_messages for delete to authenticated using(author_id=auth.uid() and public.is_group_member(group_id,auth.uid())); create index group_messages_history on public.group_messages(group_id,created_at); create function public.guard_group_message() returns trigger language plpgsql security definer set search_path=public as $$ declare consecutive integer; begin perform pg_advisory_xact_lock(hashtext(new.group_id::text)); if new.content ~* '\m([[:alnum:]_]+)[[:space:]]+\1\M' then raise exception 'Do not repeat a word twice in a row'; end if; select count(*) into consecutive from(select author_id from public.group_messages where group_id=new.group_id order by created_at desc,id desc limit 5)m where m.author_id=new.author_id; if consecutive=5 then raise exception 'Wait for someone else after 5 messages'; end if; return new; end; $$; create trigger guard_group_message before insert on public.group_messages for each row execute function public.guard_group_message();